struct SkinDefinition: Codable, Equatable, Identifiable {
    struct Effects: Codable, Equatable { var globalEffectEnabled: Bool; var globalEffectType: String }
    var schemaVersion: Int; var id: String; var name: String; var author: String?; var colors: [String: String]; var assets: [String: String]; var effects: Effects
    static let `default` = SkinDefinition(schemaVersion: 1, id: "lake-light", name: "Default / Lake Light", author: "AIQuickNote", colors: [:], assets: [:], effects: .init(globalEffectEnabled: false, globalEffectType: "none"))
}

enum SkinError: Error { case malformedArchive, unsupportedSchema, invalidManifest, unsafePath, missingAsset, invalidImage, forbiddenContent }

@MainActor final class SkinManager: ObservableObject {
    static let shared = SkinManager()
    @Published private(set) var current: SkinDefinition = .default; @Published private(set) var installed: [SkinDefinition] = []
    private var entries: [String: Data] = [:], images: [String: UIImage] = [:]; private let defaults: UserDefaults; private let folder: URL
    init(defaults: UserDefaults = .standard, folder: URL? = nil) { self.defaults = defaults; self.folder = folder ?? FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0].appendingPathComponent("Skins", isDirectory: true); reload() }
    static func validate(_ data: Data) throws -> (SkinDefinition, [String: Data]) {
        let entries: [String: Data]; do { entries = try ZipArchive.entries(in: data, requiredEntry: "skin.json") } catch { throw SkinError.malformedArchive }
        let forbidden = ["swift", "sh", "js", "dylib", "so", "framework", "app", "exe"]
        for path in entries.keys { let normalized = path.replacingOccurrences(of: "\\", with: "/"); if normalized.hasPrefix("/") || normalized.contains("../") || normalized.contains(":") { throw SkinError.unsafePath }; if forbidden.contains(URL(fileURLWithPath: normalized).pathExtension.lowercased()) { throw SkinError.forbiddenContent } }
        guard let manifest = entries["skin.json"], let skin = try? JSONDecoder().decode(SkinDefinition.self, from: manifest), !skin.id.trimmed.isEmpty, !skin.name.trimmed.isEmpty, skin.id.range(of: #"^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$"#, options: .regularExpression) != nil else { throw SkinError.invalidManifest }
        guard skin.schemaVersion == 1, ["none", "falling"].contains(skin.effects.globalEffectType) else { throw SkinError.unsupportedSchema }
        for path in skin.assets.values { guard path.hasPrefix("assets/"), let data = entries[path] else { throw SkinError.missingAsset }; guard UIImage(data: data) != nil else { throw SkinError.invalidImage } }
        return (skin, entries)
    }
    func importSkin(_ data: Data) throws { let (skin, _) = try Self.validate(data); try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true); try data.write(to: folder.appendingPathComponent("\(skin.id).aiqskin"), options: .atomic); reload(); try apply(skin.id) }
    func apply(_ id: String) throws { guard id != SkinDefinition.default.id else { current = .default; entries = [:]; images = [:]; defaults.set(id, forKey: "skin.current"); return }; let url = folder.appendingPathComponent("\(id).aiqskin"), result = try Self.validate(Data(contentsOf: url)); current = result.0; entries = result.1; images = [:]; defaults.set(id, forKey: "skin.current") }
    func delete(_ id: String) { guard id != SkinDefinition.default.id else { return }; try? FileManager.default.removeItem(at: folder.appendingPathComponent("\(id).aiqskin")); if current.id == id { try? apply(SkinDefinition.default.id) }; reload() }
    func color(_ key: String) -> Color? { current.colors[key].flatMap(Color.init(hex:)) }
    func image(_ key: String) -> UIImage? { guard let path = current.assets[key] else { return nil }; if let cached = images[path] { return cached }; guard let data = entries[path], let image = UIImage(data: data) else { return nil }; images[path] = image; return image }
    private func reload() { installed = ((try? FileManager.default.contentsOfDirectory(at: folder, includingPropertiesForKeys: nil)) ?? []).compactMap { url in guard let data = try? Data(contentsOf: url), let result = try? Self.validate(data) else { return nil }; return result.0 }; let saved = defaults.string(forKey: "skin.current") ?? SkinDefinition.default.id; do { try apply(saved) } catch { try? apply(SkinDefinition.default.id) } }
}

private extension Color { init?(hex: String) { var value = hex.trimmingCharacters(in: CharacterSet(charactersIn: "#")); guard value.count == 6 || value.count == 8 else { return nil }; if value.count == 6 { value += "FF" }; guard let raw = UInt64(value, radix: 16) else { return nil }; self.init(red: Double((raw >> 24) & 255) / 255, green: Double((raw >> 16) & 255) / 255, blue: Double((raw >> 8) & 255) / 255, opacity: Double(raw & 255) / 255) } }
private struct FallingEffect: View { let image: UIImage; var body: some View { GeometryReader { proxy in ForEach(0..<12, id: \.self) { i in Image(uiImage: image).resizable().scaledToFit().frame(width: CGFloat(18 + i % 4 * 7)).opacity(0.45).position(x: proxy.size.width * CGFloat((i * 37) % 100) / 100, y: proxy.size.height * CGFloat((i * 53) % 100) / 100) } }.allowsHitTesting(false) } }

final class IdentitySession: IdentityGate, ObservableObject, @unchecked Sendable {
    @Published private(set) var currentUser: IdentityUser?
    let legacyOwnerID: String?
    var confirmedUserID: String? { currentUser?.id }
    var isAuthenticated: Bool { currentUser != nil }
    init(defaults: UserDefaults = .standard) {
        if let data = defaults.data(forKey: "identity.currentUser"), let user = try? JSONDecoder().decode(IdentityUser.self, from: data) { currentUser = user; legacyOwnerID = nil }
        else if let legacy = defaults.string(forKey: "confirmedUserID") { currentUser = IdentityUser(id: "00000000-0000-4000-8000-000000000101", provider: .apple, providerSubject: "mock-apple-user-001", displayName: "Test User 1", email: "test1@example.invalid", createdAt: Date(timeIntervalSince1970: 0)); legacyOwnerID = legacy; persist(defaults) }
        else { currentUser = nil; legacyOwnerID = nil }
    }
    func signIn(_ user: IdentityUser, defaults: UserDefaults = .standard) { currentUser = user; persist(defaults) }
    func signOut(defaults: UserDefaults = .standard) { currentUser = nil; defaults.removeObject(forKey: "identity.currentUser"); defaults.removeObject(forKey: "confirmedUserID") }
    private func persist(_ defaults: UserDefaults) { if let currentUser, let data = try? JSONEncoder().encode(currentUser) { defaults.set(data, forKey: "identity.currentUser"); defaults.set(currentUser.id, forKey: "confirmedUserID") } }
}

enum ReminderServiceError: Error { case permissionDenied }

@MainActor final class ReminderService: ObservableObject {
    @Published private(set) var status = EKEventStore.authorizationStatus(for: .reminder)
    private let store = EKEventStore()
    var statusText: String { switch status { case .fullAccess, .writeOnly: "已允许"; case .denied, .restricted: "未允许"; case .notDetermined: "未请求"; @unknown default: "未知" } }
    func create(for record: Record) async throws -> String {
        if status == .notDetermined { _ = try await store.requestFullAccessToReminders(); status = EKEventStore.authorizationStatus(for: .reminder) }
        guard status == .fullAccess || status == .writeOnly else { throw ReminderServiceError.permissionDenied }
        let reminder = EKReminder(eventStore: store); reminder.title = record.content; reminder.calendar = store.defaultCalendarForNewReminders(); if let due = record.dueAt { reminder.dueDateComponents = Calendar.current.dateComponents(in: TimeZone.current, from: due) }; reminder.notes = "来自 AI随手记"; try store.save(reminder, commit: true); return reminder.calendarItemIdentifier
    }
    func exists(_ identifier: String) -> Bool { store.calendarItem(withIdentifier: identifier) != nil }
}

@MainActor final class AppModel: ObservableObject {
    @Published var records: [Record] = []; @Published var error: String?; @Published var loginPresented = false
    let identity: IdentitySession; let core: QuickNoteCore; let parser = DeterministicDraftParser(); let reminderService = ReminderService()
    private var pendingSave: Record?; private var pendingSaveCompletion: (() -> Void)?
    init() { let folder = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0], identity = IdentitySession(), store = FileRecordStore(url: folder.appendingPathComponent("records.json")); self.identity = identity; if let old = identity.legacyOwnerID, let new = identity.confirmedUserID, var records = try? store.load(), records.contains(where: { $0.ownerID == old }) { for index in records.indices where records[index].ownerID == old { records[index].ownerID = new }; try? store.save(records) }; core = QuickNoteCore(store: store, identity: identity); reload() }
    func reload() { do { records = try core.records() } catch { self.error = error.localizedDescription } }
    func save(_ value: Record) throws { var value = value; if value.reminderEnabled, value.reminderState == .none { value.reminderState = .requested }; let saved = try core.save(value); reload(); if saved.module == .todo, saved.reminderEnabled, saved.dueAt != nil, !saved.reminderLinked { Task { await linkReminder(saved) } } }
    func saveOrRequestIdentity(_ value: Record, onSaved: @escaping () -> Void) { do { try save(value); onSaved() } catch CoreError.identityRequired { pendingSave = value; pendingSaveCompletion = onSaved; loginPresented = true } catch { self.error = error.localizedDescription } }
    func signedIn(_ user: IdentityUser) { identity.signIn(user); loginPresented = false; reload(); guard let value = pendingSave else { return }; pendingSave = nil; do { try save(value); let completion = pendingSaveCompletion; pendingSaveCompletion = nil; completion?() } catch { self.error = error.localizedDescription } }
    func signOut() { identity.signOut(); pendingSave = nil; pendingSaveCompletion = nil; reload() }
    func exportData() throws -> Data { try ExportService.makeExport(records: records, users: identity.currentUser.map { [$0] } ?? []) }
    func backupData() throws -> Data { try BackupService.makeBackup(records: records, users: identity.currentUser.map { [$0] } ?? [], settings: ["theme": "lake-light"]) }
    func restoreBackup(_ data: Data) throws { let payload = try BackupService.validateAndRead(data); try core.replaceCurrentOwnerRecords(with: payload.records); reload() }
    func reconcileReminder(_ value: Record) -> Record { guard value.reminderState == .active, let id = value.reminderExternalID, !reminderService.exists(id) else { return value }; var missing = value; missing.reminderLinked = false; missing.reminderState = .missingExternalReminder; _ = try? core.save(missing); reload(); return missing }
    private func linkReminder(_ saved: Record) async { do { var linked = saved; linked.reminderExternalID = try await reminderService.create(for: saved); linked.reminderLinked = true; linked.reminderState = .active; _ = try core.save(linked); reload() } catch { var failed = saved; failed.reminderLinked = false; failed.reminderExternalID = nil; failed.reminderState = reminderService.status == .denied || reminderService.status == .restricted ? .permissionDenied : .requested; _ = try? core.save(failed); reload(); self.error = failed.reminderState == .permissionDenied ? "提醒事项权限已关闭，请在系统设置中允许 AI随手记访问提醒事项。" : "记录已保存，但未写入系统提醒事项。" } }
}

