private let backupContentType = UTType(exportedAs: "com.example.aiquicknote.backup", conformingTo: .data)
private let skinContentType = UTType(importedAs: "com.example.aiquicknote.skin", conformingTo: .zip)

struct DataDocument: FileDocument {
    static var readableContentTypes: [UTType] { [.zip, backupContentType] }
    var data: Data
    init(_ data: Data) { self.data = data }
    init(configuration: ReadConfiguration) throws { guard let data = configuration.file.regularFileContents else { throw CocoaError(.fileReadCorruptFile) }; self.data = data }
    func fileWrapper(configuration: WriteConfiguration) throws -> FileWrapper { FileWrapper(regularFileWithContents: data) }
}

struct DataBackupView: View {
    @EnvironmentObject private var model: AppModel; @State private var document: DataDocument?; @State private var exporting = false; @State private var importing = false; @State private var restoreConfirmation = false; @State private var pendingRestore: Data?; @State private var filename = ""; @State private var contentType = UTType.zip
    var body: some View { Form { Section("Data") { Button("Export Data") { prepareExport() }; Button("Backup Now") { prepareBackup() }; Button("Restore Backup") { importing = true } }; Section("System Integration") { LabeledContent("Reminders Permission / Status", value: model.reminderService.statusText) }; Section { Text("导出与备份只包含当前登录用户的本地记录和身份元数据，不包含密码、token 或 Keychain secrets。").font(.footnote).foregroundStyle(.secondary) } }.navigationTitle("设置").fileExporter(isPresented: $exporting, document: document, contentType: contentType, defaultFilename: filename) { if case .failure(let error) = $0 { model.error = error.localizedDescription } }.fileImporter(isPresented: $importing, allowedContentTypes: [backupContentType, .data]) { result in do { let url = try result.get(), scoped = url.startAccessingSecurityScopedResource(); defer { if scoped { url.stopAccessingSecurityScopedResource() } }; pendingRestore = try Data(contentsOf: url); _ = try BackupService.validateAndRead(pendingRestore!); restoreConfirmation = true } catch { model.error = "备份文件无效，现有数据未更改。" } }.confirmationDialog("恢复备份会覆盖当前登录用户的本地记录", isPresented: $restoreConfirmation, titleVisibility: .visible) { Button("覆盖并恢复", role: .destructive) { guard let pendingRestore else { return }; do { try model.restoreBackup(pendingRestore) } catch { model.error = "恢复失败，现有数据未更改。" } }; Button("取消", role: .cancel) {} } }
    private var dateStamp: String { let formatter = DateFormatter(); formatter.dateFormat = "yyyy-MM-dd"; return formatter.string(from: Date()) }
    private func prepareExport() { do { document = DataDocument(try model.exportData()); filename = "AIQuickNote-Export-\(dateStamp).zip"; contentType = .zip; exporting = true } catch { model.error = error.localizedDescription } }
    private func prepareBackup() { do { document = DataDocument(try model.backupData()); filename = "AIQuickNote-Backup-\(dateStamp).aiqnbackup"; contentType = backupContentType; exporting = true } catch { model.error = error.localizedDescription } }
}

