struct SharePrivacyOptions: Equatable { var showAmount = true; var showDateTime = true; var showTags = true; var showMerchantOrLocation = true }

enum SharePresentation {
    static func text(for record: Record, showAmount: Bool) -> String { guard !showAmount else { return record.content }; var text = record.content; for item in record.amountItems { let value = NSRegularExpression.escapedPattern(for: String(describing: item.value)), aliases: String; switch CurrencyCanonicalizer.canonical(item.currency) { case "USD": aliases = #"(?:USD|美元|美金|dollars?|\$)"#; case "JPY": aliases = #"(?:JPY|日元|yen|¥|￥)"#; case "EUR": aliases = #"(?:EUR|欧元|欧|euros?|€)"#; case "CNY": aliases = #"(?:CNY|RMB|人民币|元|块|¥|￥)"#; default: continue }; text = text.replacingOccurrences(of: #"(?:\#(aliases)\s*\#(value)|\#(value)\s*\#(aliases))"#, with: "•••", options: [.regularExpression, .caseInsensitive]) }; return text }
}

@MainActor enum ShareCardRenderer {
    static func png(records: [Record], options: SharePrivacyOptions, pageLabel: String? = nil) -> Data? { guard !records.isEmpty else { return nil }; let renderer = ImageRenderer(content: ShareCardView(records: records, options: options, pageLabel: pageLabel)); renderer.scale = 2; renderer.proposedSize = ProposedViewSize(width: 540, height: nil); return renderer.uiImage?.pngData() }
}

private struct ShareCardView: View {
    let records: [Record]; let options: SharePrivacyOptions; let pageLabel: String?
    var body: some View { VStack(alignment: .leading, spacing: 18) { HStack { Image(systemName: records.count == 1 ? (records.first?.module.icon ?? "note.text") : "sparkles").font(.title); Text(records.count == 1 ? (records.first?.module.title ?? "记录") : "搜索结果摘要").font(.title.bold()); Spacer(); if let pageLabel { Text(pageLabel).font(.caption).foregroundStyle(.secondary) }; if records.first?.important == true { Image(systemName: "star.fill").foregroundStyle(.orange) } }; ForEach(records.prefix(10)) { record in VStack(alignment: .leading, spacing: 8) { Text(SharePresentation.text(for: record, showAmount: options.showAmount)).font(.title3.bold()).fixedSize(horizontal: false, vertical: true); if record.module == .ledger, options.showAmount { ForEach(record.amountItems, id: \.self) { Text("\(CurrencyCanonicalizer.displayName($0.currency, languageCode: appLanguageCode) ?? "") \($0.value)").font(.headline).foregroundStyle(.blue) } }; if record.module == .todo, let status = record.status { Text(status.rawValue).foregroundStyle(.green) }; if options.showMerchantOrLocation { Text([record.merchant, record.location, record.paymentMethod].compactMap { $0 }.joined(separator: " · ")).font(.subheadline).foregroundStyle(.secondary) }; if options.showDateTime { Text(record.dueAt ?? record.occurredAt ?? record.createdAt, style: .date).font(.subheadline).foregroundStyle(.secondary) }; if options.showTags, !record.tags.isEmpty { Text(record.tags.map { "#\($0)" }.joined(separator: "  ")).font(.caption).foregroundStyle(.indigo) } }.padding(16).frame(maxWidth: .infinity, alignment: .leading).background(.white.opacity(0.82), in: RoundedRectangle(cornerRadius: 20)) }; Divider(); HStack { Spacer(); Image(systemName: "sparkles"); Text("AI随手记").font(.footnote.bold()) }.foregroundStyle(.secondary) }.padding(28).frame(width: 540).background(AppTheme.background) }
}

private struct ShareFile: Identifiable { let id = UUID(); let url: URL }
struct ShareOptionsView: View {
    @Environment(\.dismiss) private var dismiss; @State private var options = SharePrivacyOptions(); @State private var file: ShareFile?; let records: [Record]; var pageLabel: String? = nil
    var body: some View { NavigationStack { Form { Toggle("显示金额", isOn: $options.showAmount); Toggle("显示日期时间", isOn: $options.showDateTime); Toggle("显示标签", isOn: $options.showTags); Toggle("显示商家或地点", isOn: $options.showMerchantOrLocation); Button("生成 PNG 并分享") { share() }.buttonStyle(.borderedProminent).disabled(records.isEmpty) }.navigationTitle(records.count == 1 ? "分享记录" : "分享搜索摘要").toolbar { Button("取消") { dismiss() } }.sheet(item: $file) { ShareSheet(items: [$0.url]) } } }
    private func share() { guard let png = ShareCardRenderer.png(records: records, options: options, pageLabel: pageLabel) else { return }; let url = FileManager.default.temporaryDirectory.appendingPathComponent("AIQuickNote-Share-\(UUID().uuidString).png"); do { try png.write(to: url, options: .atomic); file = ShareFile(url: url) } catch {} }
}

struct ShareSheet: UIViewControllerRepresentable { let items: [Any]; func makeUIViewController(context: Context) -> UIActivityViewController { UIActivityViewController(activityItems: items, applicationActivities: nil) }; func updateUIViewController(_ uiViewController: UIActivityViewController, context: Context) {} }

