            .background(LakeBackground()).safeAreaInset(edge: .bottom) { captureBar }.toolbar(.hidden, for: .navigationBar)
            .navigationDestination(for: Module.self) { ModuleListView(module: $0) }.navigationDestination(item: $draft) { ReviewView(draft: $0) { text = "" } }
            .navigationDestination(isPresented: Binding(get: { query != nil }, set: { if !$0 { query = nil } })) { SearchView(initialQuery: query ?? RecordQuery()) }
            .confirmationDialog("添加图片", isPresented: $attachmentMenu) { Button("拍照") { if UIImagePickerController.isSourceTypeAvailable(.camera) { camera = true } else { model.error = "当前设备没有可用相机。" } }; Button("从相册选择") { photos = true }; Button("取消", role: .cancel) {} }
            .photosPicker(isPresented: $photos, selection: $photo, matching: .images).sheet(isPresented: $camera) { CameraPicker() }
            .sheet(isPresented: $accountPresented) { SettingsView() }
            .onAppear { model.reload(); focused = nil }.onDisappear { focused = nil; speech.stop() }
            .onChange(of: speech.transcript) { text = $0 }.onChange(of: speech.finishedTranscript) { if $0 != nil { submit() } }.onChange(of: speech.error) { if let value = $0 { model.error = value } }
    }
    private var captureBar: some View { HStack(spacing: 12) {
        Button { focused = nil; speech.isRecording ? speech.stop() : speech.start() } label: { Image(systemName: speech.isRecording ? "stop.fill" : "mic.fill").font(.system(size: 34, weight: .semibold)).frame(width: 84, height: 84).background(speech.isRecording ? AnyShapeStyle(.red) : AnyShapeStyle(LinearGradient(colors: [.blue.opacity(0.65), .cyan.opacity(0.45)], startPoint: .topLeading, endPoint: .bottomTrailing))).foregroundStyle(.white).clipShape(Circle()).overlay(Circle().stroke(.white.opacity(0.9), lineWidth: 1)).shadow(color: .blue.opacity(0.3), radius: 16, y: 7) }.accessibilityLabel("语音输入")
        HStack(spacing: 8) { TextField("说一句，或输入搜索", text: $text, axis: .vertical).focused($focused, equals: .homeInput).lineLimit(1...3).submitLabel(.search).onSubmit { openSearch() }; if !text.isEmpty { Button { text = "" } label: { Image(systemName: "xmark.circle.fill").foregroundStyle(.secondary) }.accessibilityLabel("清空输入") }; Button { openSearch() } label: { Image(systemName: "magnifyingglass").font(.title2).foregroundStyle(.blue.opacity(0.8)) }.accessibilityLabel("搜索") }.padding(.horizontal, 18).frame(minHeight: 70).background(.white.opacity(0.72), in: Capsule()).overlay(Capsule().stroke(.white.opacity(0.9), lineWidth: 1)).shadow(color: .blue.opacity(0.12), radius: 12, y: 5)
        Button { focused = nil; if text.trimmed.isEmpty { attachmentMenu = true } else { submit() } } label: { Image(systemName: text.trimmed.isEmpty ? "plus" : "arrow.up").font(.system(size: 27, weight: .semibold)).frame(width: 64, height: 64).background(.white.opacity(0.8), in: Circle()).overlay(Circle().stroke(.white.opacity(0.9), lineWidth: 1)).shadow(color: .blue.opacity(0.15), radius: 10, y: 4) }.accessibilityLabel(text.trimmed.isEmpty ? "添加图片" : "提交")
    }.padding(.horizontal, 14).padding(.vertical, 12).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 36)).padding(.horizontal, 8).shadow(color: .black.opacity(0.08), radius: 16, y: -3) }
    private func submit() { let input = text.trimmed; guard !input.isEmpty else { return }; focused = nil; speech.stop(); Task { do { switch try await model.parser.parse(input) { case .create(let value): draft = value; case .search(let value): query = value } } catch { draft = Record(module: .memo, rawInput: input); model.error = "解析不可用，已保留原文供手工填写。" } } }
    private func openSearch() { focused = nil; speech.stop(); query = RecordQuery(keyword: text.trimmed) }
