struct ReviewView: View {
    @EnvironmentObject private var model: AppModel; @Environment(\.dismiss) private var dismiss; @StateObject private var speech = SpeechInput(); @State var draft: Record; @State private var searchQuery: RecordQuery?; @State private var voicePrefix = ""; let onSaved: () -> Void
    var body: some View { RecordForm(record: $draft, showRawInput: true, saveTitle: "确认保存", onSave: save, onSearch: search, onReparse: { reparse() }, onVoice: toggleVoice, isRecording: speech.isRecording, voiceLabel: speech.statusText).navigationTitle("确认记录").navigationBarTitleDisplayMode(.inline).navigationDestination(isPresented: Binding(get: { searchQuery != nil }, set: { if !$0 { searchQuery = nil } })) { SearchView(initialQuery: searchQuery ?? RecordQuery()) }.task(id: draft.rawInput) { try? await Task.sleep(for: .milliseconds(400)); guard !Task.isCancelled else { return }; await parseCurrentInput() }.onChange(of: speech.transcript) { let value = $0.trimmed; guard !value.isEmpty else { return }; draft.rawInput = [voicePrefix, value].filter { !$0.isEmpty }.joined(separator: "，") }.onChange(of: speech.error) { if let value = $0 { model.error = value } }.onDisappear { speech.stop() } }
    private func save(_ value: Record) { model.saveOrRequestIdentity(value) { onSaved(); dismiss() } }
    private func search(_ value: Record) { draft = value; searchQuery = RecordQuery(keyword: value.merchant ?? value.paymentMethod ?? value.content, modules: [value.module], importantOnly: value.important, tags: value.tags) }
    private func reparse() { Task { await parseCurrentInput() } }
    private func toggleVoice() { if speech.isRecording { speech.stop() } else { voicePrefix = draft.rawInput.trimmed; speech.start() } }
    private func parseCurrentInput() async { let input = draft.rawInput.trimmed; guard !input.isEmpty else { return }; do { if case .create(var value) = try await model.parser.parse(input) { value.id = draft.id; value.ownerID = draft.ownerID; value.createdAt = draft.createdAt; draft = value } } catch { model.error = "重新解析失败，已保留当前内容。" } }
}

