    var body: some View { List(model.records.filter { $0.module == module }) { record in NavigationLink(value: record) { RecordRow(record: record) }.listRowBackground(Color.white.opacity(0.78)) }.listStyle(.insetGrouped).scrollContentBackground(.hidden).scrollDismissesKeyboard(.interactively).background(LakeBackground()).navigationTitle(module.title).toolbar { Button { adding = true } label: { Image(systemName: "plus") } }.sheet(isPresented: $adding) { NavigationStack { ModuleComposerView(module: module) } }.navigationDestination(for: Record.self) { DetailView(record: $0) }.overlay { if model.records.allSatisfy({ $0.module != module }) { if let image = SkinManager.shared.image("emptyStateDecoration") { ContentUnavailableView { Label("暂无记录", systemImage: module.icon) } description: { Image(uiImage: image).resizable().scaledToFit().frame(width: 150, height: 150) } } else { ContentUnavailableView("暂无记录", systemImage: module.icon) } } }.onAppear { model.reload() } }
}

