struct CameraPicker: UIViewControllerRepresentable {
    @Environment(\.dismiss) private var dismiss
    func makeCoordinator() -> Coordinator { Coordinator(dismiss: dismiss) }
    func makeUIViewController(context: Context) -> UIImagePickerController { let picker = UIImagePickerController(); picker.sourceType = .camera; picker.delegate = context.coordinator; return picker }
    func updateUIViewController(_ uiViewController: UIImagePickerController, context: Context) {}
    final class Coordinator: NSObject, UIImagePickerControllerDelegate, UINavigationControllerDelegate { let dismiss: DismissAction; init(dismiss: DismissAction) { self.dismiss = dismiss }; func imagePickerController(_ picker: UIImagePickerController, didFinishPickingMediaWithInfo info: [UIImagePickerController.InfoKey: Any]) { dismiss() }; func imagePickerControllerDidCancel(_ picker: UIImagePickerController) { dismiss() } }
}

@MainActor final class SpeechInput: ObservableObject {
    enum Phase { case idle, listening, processing }
    @Published var transcript = ""; @Published var finishedTranscript: String?; @Published var phase: Phase = .idle; @Published var error: String?
    var isRecording: Bool { phase == .listening }; var statusText: String { phase == .listening ? "正在听…" : phase == .processing ? "正在识别…" : "语音补充" }
    let primaryLocale = Locale(identifier: "zh-CN")
    let secondaryLocale = Locale(identifier: "en-US")
    private let engine = AVAudioEngine(); private var task: SFSpeechRecognitionTask?; private var request: SFSpeechAudioBufferRecognitionRequest?; private var tapInstalled = false
    func start() { SFSpeechRecognizer.requestAuthorization { [weak self] status in Task { @MainActor in guard status == .authorized else { self?.error = "请允许语音识别权限。"; return }; AVAudioApplication.requestRecordPermission { allowed in Task { @MainActor in guard allowed else { self?.error = "请允许麦克风权限。"; return }; self?.begin() } } } } }
    private func begin() { tearDown(); transcript = ""; finishedTranscript = nil; guard let recognizer = SFSpeechRecognizer(locale: primaryLocale), recognizer.isAvailable else { error = "系统语音识别不可用。"; return }; let request = SFSpeechAudioBufferRecognitionRequest(); request.shouldReportPartialResults = true; request.contextualStrings = ["沃尔玛", "Target", "Costco", "Amazon", "Visa", "Starbucks", "iPhone"]; self.request = request; let node = engine.inputNode; node.installTap(onBus: 0, bufferSize: 1024, format: node.outputFormat(forBus: 0)) { buffer, _ in request.append(buffer) }; tapInstalled = true; task = recognizer.recognitionTask(with: request) { [weak self] result, failure in Task { @MainActor in guard let self else { return }; if let result { self.transcript = result.bestTranscription.formattedString }; if failure != nil || result?.isFinal == true { self.finish() } } }; do { try AVAudioSession.sharedInstance().setCategory(.record, mode: .measurement); try AVAudioSession.sharedInstance().setActive(true); engine.prepare(); try engine.start(); phase = .listening } catch { tearDown(); self.error = "无法启动麦克风：\(error.localizedDescription)" } }
    private func finish() { guard request != nil || task != nil else { return }; phase = .processing; let finalText = transcript; tearDown(); if !finalText.trimmed.isEmpty { finishedTranscript = finalText }; phase = .idle }
    func stop() { guard phase != .idle else { return }; finish() }
    private func tearDown() { if engine.isRunning { engine.stop() }; if tapInstalled { engine.inputNode.removeTap(onBus: 0); tapInstalled = false }; request?.endAudio(); task?.cancel(); request = nil; task = nil }
}

private extension String { var trimmed: String { trimmingCharacters(in: .whitespacesAndNewlines) }; var csv: [String] { split(separator: ",").map { String($0).trimmed }.filter { !$0.isEmpty } } }
@MainActor private extension Module { var icon: String { switch self { case .ledger: "chart.bar.fill"; case .todo: "checkmark.square.fill"; case .memo: "note.text"; case .idea: "lightbulb.fill" } }; var decoration: String { switch self { case .ledger: "creditcard.fill"; case .todo: "checklist"; case .memo: "note.text"; case .idea: "sparkles" } }; var subtitle: String { switch self { case .ledger: "轻松记账，清楚每一笔"; case .todo: "记下任务，安心完成"; case .memo: "随手记录，整理生活"; case .idea: "闪现的想法，值得记录" } }; var color: Color { switch self { case .ledger: AppTheme.ledgerAccent; case .todo: AppTheme.todoAccent; case .memo: AppTheme.memoAccent; case .idea: AppTheme.ideaAccent } } }
